The following code is a simple context manager that acquires three resources in order. If any step fails, all previously acquired resources are released.
import contextlib
class ThreeResources:
    def __init__(self):
        self.r1 = None
        self.r2 = None
        self.r3 = None
    def __enter__(self):
        try:
            self.r1 = Resource('r1')
            self.r2 = Resource('r2')
            self.r3 = Resource('r3')
        except:
            self.__exit__(None, None, None)
            raise
        return self
    def __exit__(self, exc_type, exc_value, traceback):
        if self.r3 is not None:
            self.r3.close()
        if self.r2 is not None:
            self.r2.close()
        if self.r1 is not None:
            self.r1.close()
with ThreeResources() as tr:
    print(tr.r1, tr.r2, tr.r3)
